    private int gain(TreeNode n){if(n==null)return 0;int l=Math.max(0,gain(n.left)),r=Math.max(0,gain(n.right));best=Math.max(best,n.val+l+r);return n.val+Math.max(l,r);}
}

class Solution:
    def isPalindrome(self, s: str) -> bool:
        l,r=0,len(s)-1
        while l<r:
            while l<r and not s[l].isalnum():l+=1
            while l<r and not s[r].isalnum():r-=1
            if s[l].casefold()!=s[r].casefold():return False
            l+=1;r-=1
        return True

class Solution {
    public boolean isPalindrome(String s){int l=0,r=s.length()-1;while(l<r){while(l<r&&!Character.isLetterOrDigit(s.charAt(l)))l++;while(l<r&&!Character.isLetterOrDigit(s.charAt(r)))r--;if(Character.toLowerCase(s.charAt(l))!=Character.toLowerCase(s.charAt(r)))return false;l++;r--;}return true;}
