class Solution:
    def findLadders(self, beginWord: str, endWord: str, wordList: List[str]) -> List[List[str]]:
        words=set(wordList)
        if endWord not in words:return []
        parents=defaultdict(list);front={beginWord};found=False
        while front and not found:
            words-=front;next_level=set()
            for word in front:
                chars=list(word)
                for i,old in enumerate(chars):
                    for ch in 'abcdefghijklmnopqrstuvwxyz':
                        if ch==old:continue
                        chars[i]=ch;candidate=''.join(chars)
                        if candidate in words:
                            next_level.add(candidate);parents[candidate].append(word)
                            if candidate==endWord:found=True
                    chars[i]=old
            front=next_level
        if not found:return []
        out=[];path=[endWord]
        def build(word):
            if word==beginWord:out.append(path[::-1]);return
            for parent in parents[word]:path.append(parent);build(parent);path.pop()
        build(endWord);return out

import java.util.*;

class Solution {
    public List<List<String>> findLadders(String beginWord,String endWord,List<String> wordList){Set<String>words=new HashSet<>(wordList);List<List<String>>out=new ArrayList<>();if(!words.contains(endWord))return out;Map<String,List<String>>parents=new HashMap<>();Set<String>front=new HashSet<>();front.add(beginWord);boolean found=false;
        while(!front.isEmpty()&&!found){words.removeAll(front);Set<String>next=new HashSet<>();for(String w:front){char[]a=w.toCharArray();for(int i=0;i<a.length;i++){char old=a[i];for(char ch='a';ch<='z';ch++){if(ch==old)continue;a[i]=ch;String v=new String(a);if(words.contains(v)){next.add(v);parents.computeIfAbsent(v,k->new ArrayList<>()).add(w);if(v.equals(endWord))found=true;}}a[i]=old;}}front=next;}
        if(!found)return out;List<String>path=new ArrayList<>();path.add(endWord);build(endWord,beginWord,parents,path,out);return out;}
    private void build(String w,String begin,Map<String,List<String>>p,List<String>path,List<List<String>>out){if(w.equals(begin)){List<String>x=new ArrayList<>(path);Collections.reverse(x);out.add(x);return;}for(String par:p.getOrDefault(w,List.of())){path.add(par);build(par,begin,p,path,out);path.remove(path.size()-1);}}
}

