from collections import deque

class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: List[str]) -> int:
        words=set(wordList)
        if endWord not in words:return 0
        q=deque([(beginWord,1)]);words.discard(beginWord)
        while q:
            word,d=q.popleft()
            if word==endWord:return d
            chars=list(word)
            for i,old in enumerate(chars):
                for ch in 'abcdefghijklmnopqrstuvwxyz':
                    if ch==old:continue
                    chars[i]=ch;v=''.join(chars)
                    if v in words:words.remove(v);q.append((v,d+1))
                chars[i]=old
        return 0

