class Solution {
    public int ladderLength(String beginWord,String endWord,List<String> wordList){Set<String>words=new HashSet<>(wordList);if(!words.contains(endWord))return 0;Queue<String>q=new ArrayDeque<>();q.offer(beginWord);words.remove(beginWord);int level=1;while(!q.isEmpty()){for(int size=q.size();size>0;size--){String w=q.poll();if(w.equals(endWord))return level;char[]a=w.toCharArray();for(int i=0;i<a.length;i++){char old=a[i];for(char c='a';c<='z';c++){if(c==old)continue;a[i]=c;String v=new String(a);if(words.remove(v))q.offer(v);}a[i]=old;}}level++;}return 0;}
