class Solution:
    def sumNumbers(self, root: Optional[TreeNode]) -> int:
        def dfs(node,prefix):
            if not node:return 0
            value=prefix*10+node.val
            if not node.left and not node.right:return value
            return dfs(node.left,value)+dfs(node.right,value)
        return dfs(root,0)

class Solution {
    public int sumNumbers(TreeNode root){return dfs(root,0);}
    private int dfs(TreeNode n,int prefix){if(n==null)return 0;int v=prefix*10+n.val;if(n.left==null&&n.right==null)return v;return dfs(n.left,v)+dfs(n.right,v);}
}

