class Solution:
    def solve(self, board: List[List[str]]) -> None:
        if not board:return
        m,n=len(board),len(board[0]);q=deque()
        for r in range(m):
            for c in (0,n-1):
                if board[r][c]=='O':board[r][c]='#';q.append((r,c))
        for c in range(n):
            for r in (0,m-1):
                if board[r][c]=='O':board[r][c]='#';q.append((r,c))
        while q:
            r,c=q.popleft()
            for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if 0<=nr<m and 0<=nc<n and board[nr][nc]=='O':board[nr][nc]='#';q.append((nr,nc))
        for r in range(m):
            for c in range(n):board[r][c]='O' if board[r][c]=='#' else ('X' if board[r][c]=='O' else board[r][c])

import java.util.*;

class Solution {
    public void solve(char[][]b){if(b.length==0)return;int m=b.length,n=b[0].length;Queue<int[]>q=new ArrayDeque<>();for(int r=0;r<m;r++){mark(b,r,0,q);mark(b,r,n-1,q);}for(int c=0;c<n;c++){mark(b,0,c,q);mark(b,m-1,c,q);}int[][]dirs={{1,0},{-1,0},{0,1},{0,-1}};while(!q.isEmpty()){int[]p=q.poll();for(int[]d:dirs){int r=p[0]+d[0],c=p[1]+d[1];if(r>=0&&r<m&&c>=0&&c<n&&b[r][c]=='O')mark(b,r,c,q);}}for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(b[r][c]=='#')b[r][c]='O';else if(b[r][c]=='O')b[r][c]='X';}
    private void mark(char[][]b,int r,int c,Queue<int[]>q){if(b[r][c]=='O'){b[r][c]='#';q.offer(new int[]{r,c});}}
}
